def count_solutions(p):
    count = 0
    for a in range(p):
        for b in range(p):
            if (a*a + b*b) % p == 0:
                count += 1
    return count

print(f"p=5: {count_solutions(5)}")
print(f"p=13: {count_solutions(13)}")
